'use client';

import React, { useState } from 'react';
import { useStore } from '@/store/useStore';
import { Search, SlidersHorizontal, ShoppingBag, Star, RefreshCcw } from 'lucide-react';
import Link from 'next/link';

export default function ProductListingPage() {
  const {
    products,
    categories,
    selectedCategory,
    setSelectedCategory,
    addToCart,
  } = useStore();

  const [search, setSearch] = useState('');
  const [maxPrice, setMaxPrice] = useState(500);

  const filtered = products.filter(p => {
    const matchSearch = p.name.toLowerCase().includes(search.toLowerCase()) || p.sku.toLowerCase().includes(search.toLowerCase());
    const matchCategory = selectedCategory === 'All' || p.category === selectedCategory;
    const matchPrice = p.price <= maxPrice;
    return matchSearch && matchCategory && matchPrice;
  });

  return (
    <div className="max-w-[1440px] mx-auto py-10 px-4 lg:px-8 animate-slide-up">
      <div className="border-b border-neutral-light pb-6 mb-8">
        <h1 className="text-3xl font-extrabold text-neutral-dark">Marketplace Catalog</h1>
        <p className="text-xs text-neutral-muted mt-1">Explore all premium products, SKU models, and active vendor listings.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Sidebar Filters */}
        <div className="bg-white p-6 rounded-lg border border-neutral-light shadow-card h-fit space-y-6">
          <div>
            <h3 className="text-xs font-bold text-neutral-dark uppercase tracking-wider mb-3">Search Keywords</h3>
            <div className="flex items-center border border-neutral-light bg-neutral-light rounded p-2 text-xs">
              <Search className="w-4 h-4 text-neutral-muted mr-2" />
              <input
                type="text"
                placeholder="Product name, SKU..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="bg-transparent w-full outline-none text-neutral-dark"
              />
            </div>
          </div>

          <div>
            <h3 className="text-xs font-bold text-neutral-dark uppercase tracking-wider mb-3">Categories</h3>
            <div className="flex flex-col gap-2">
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategory(cat)}
                  className={`text-left text-xs py-1.5 px-3 rounded transition-colors font-semibold ${
                    selectedCategory === cat ? 'bg-primary text-neutral-dark font-bold' : 'hover:bg-neutral-light text-neutral-dark'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-xs font-bold text-neutral-dark uppercase tracking-wider mb-3">Price Cap (${maxPrice})</h3>
            <input
              type="range"
              min="0"
              max="500"
              step="10"
              value={maxPrice}
              onChange={(e) => setMaxPrice(parseInt(e.target.value))}
              className="w-full accent-primary"
            />
            <div className="flex justify-between text-[10px] text-neutral-muted mt-1 font-bold">
              <span>$0</span>
              <span>$500</span>
            </div>
          </div>

          <button
            onClick={() => {
              setSearch('');
              setSelectedCategory('All');
              setMaxPrice(500);
            }}
            className="w-full border border-neutral-dark text-neutral-dark hover:bg-neutral-light text-xs font-bold py-2 rounded transition-colors"
          >
            Clear Filters
          </button>
        </div>

        {/* Product Grid */}
        <div className="lg:col-span-3">
          {filtered.length === 0 ? (
            <div className="bg-white text-center py-20 rounded-lg border border-neutral-light shadow-card">
              <p className="text-sm font-bold text-neutral-muted">No items matched your filters.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {filtered.map((p) => (
                <div
                  key={p.id}
                  className="bg-white rounded-lg border border-neutral-light hover:border-primary hover:shadow-glow transition-all overflow-hidden flex flex-col justify-between"
                >
                  <div className="relative aspect-video bg-neutral-light overflow-hidden">
                    <img src={p.image} alt={p.name} className="object-cover w-full h-full" />
                  </div>
                  <div className="p-4 flex-grow flex flex-col justify-between">
                    <div>
                      <p className="text-[9px] text-neutral-muted font-bold uppercase">{p.category}</p>
                      <h3 className="text-xs font-bold text-neutral-dark mt-1 line-clamp-1">{p.name}</h3>
                      <p className="text-[10px] text-neutral-muted mt-1 line-clamp-2">{p.description}</p>
                    </div>
                    <div className="mt-4 pt-4 border-t border-neutral-light flex items-center justify-between">
                      <span className="text-sm font-extrabold text-neutral-dark">৳{p.price.toFixed(2)}</span>
                      <span className="text-[10px] text-success font-semibold">{p.stock} units left</span>
                    </div>
                  </div>
                  <div className="px-4 pb-4">
                    <button
                      onClick={() => {
                        addToCart(p);
                        alert(`${p.name} added to cart!`);
                      }}
                      className="w-full bg-primary hover:bg-primary-dark text-neutral-dark text-xs font-bold py-2 rounded flex items-center justify-center gap-1.5 transition-colors cursor-pointer"
                    >
                      <ShoppingBag className="w-3.5 h-3.5" />
                      Add to Cart
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, use } from 'react';
import { useStore, Product } from '@/store/useStore';
import { Star, ShieldAlert, CheckCircle, ShoppingCart, ArrowLeft, Send } from 'lucide-react';
import Link from 'next/link';
import { useIsMobile } from '@/hooks/useIsMobile';
import MobileProductPage from '@/components/mobile-product-page';

export default function ProductDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params);
  const { products, addToCart, fetchProducts } = useStore();
  const [liveProduct, setLiveProduct] = useState<Product | null>(null);

  const { isMobile, isMounted } = useIsMobile();

  useEffect(() => {
    if (products.length === 0) {
      fetchProducts();
    }
    fetch(`/api/products/${resolvedParams.id}`)
      .then(res => res.json())
      .then(data => {
        if (data.product) setLiveProduct(data.product);
      })
      .catch(() => {});
  }, [resolvedParams.id, fetchProducts, products.length]);

  const product = liveProduct || products.find((p) => p.id === resolvedParams.id);

  if (!product) {
    return (
      <div className="min-h-[60vh] flex flex-col items-center justify-center p-8 text-center space-y-4">
        <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
        <p className="text-sm font-bold text-slate-400">Loading product details...</p>
        <Link href="/" className="text-xs text-primary font-bold hover:underline">
          Return to Marketplace
        </Link>
      </div>
    );
  }

  if (isMobile && isMounted) {
    return <MobileProductPage product={product} />;
  }

  const [quantity, setQuantity] = useState(1);
  const [reviews, setReviews] = useState([
    { author: 'Imtiaz Alam', rating: 5, date: '2026-07-11', text: 'Stunning audio clarity! The noise cancellation blocks office chatter completely. Worth the price.' },
    { author: 'Farhana Yeasmin', rating: 4, date: '2026-07-08', text: 'Comfortable fit for long hours. Premium yellow highlighting on Zibonbaba packaging looked amazing.' }
  ]);
  const [newAuthor, setNewAuthor] = useState('');
  const [newRating, setNewRating] = useState(5);
  const [newText, setNewText] = useState('');
  const [reviewSuccess, setReviewSuccess] = useState(false);

  const handleAddReview = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAuthor || !newText) {
      alert('Please fill out name and review text.');
      return;
    }
    const newRev = {
      author: newAuthor,
      rating: newRating,
      date: new Date().toISOString().split('T')[0],
      text: newText,
    };
    setReviews([newRev, ...reviews]);
    setNewAuthor('');
    setNewText('');
    setReviewSuccess(true);
    setTimeout(() => setReviewSuccess(false), 3000);
  };

  return (
    <div className="max-w-[1440px] mx-auto py-10 px-4 lg:px-8 animate-slide-up space-y-10">
      {/* Back to Shop link */}
      <div>
        <Link href="/" className="inline-flex items-center gap-1.5 text-xs font-bold text-neutral-dark hover:text-primary-dark transition-colors">
          <ArrowLeft className="w-4 h-4" />
          Back to Marketplace
        </Link>
      </div>

      {/* Main product columns */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 bg-white p-6 lg:p-10 rounded-lg border border-neutral-light shadow-card">
        {/* Left Column: Image Container */}
        <div className="space-y-4">
          <div className="relative aspect-square bg-neutral-light rounded-lg overflow-hidden border border-neutral-light">
            <img src={product.image} alt={product.name} className="object-cover w-full h-full" />
          </div>
          <div className="grid grid-cols-3 gap-4">
            <div className="aspect-square bg-neutral-light rounded overflow-hidden border-2 border-primary border-dashed">
              <img src={product.image} alt="Thumbnail 1" className="object-cover w-full h-full opacity-80" />
            </div>
            <div className="aspect-square bg-neutral-light rounded overflow-hidden border border-neutral-light">
              <img src={product.image} alt="Thumbnail 2" className="object-cover w-full h-full opacity-60 hover:opacity-100 transition-opacity" />
            </div>
            <div className="aspect-square bg-neutral-light rounded overflow-hidden border border-neutral-light">
              <img src={product.image} alt="Thumbnail 3" className="object-cover w-full h-full opacity-60 hover:opacity-100 transition-opacity" />
            </div>
          </div>
        </div>

        {/* Right Column: Meta details and checkout options */}
        <div className="space-y-6">
          <div>
            <div className="flex items-center gap-2">
              <span className="bg-primary/20 text-neutral-dark text-[10px] font-bold px-2 py-0.5 rounded-full uppercase">
                Verified Seller: {product.vendor}
              </span>
              <span className="text-xs font-semibold text-success flex items-center gap-1">
                <CheckCircle className="w-3.5 h-3.5" /> In Stock
              </span>
            </div>
            <h1 className="text-3xl font-extrabold text-neutral-dark mt-3">{product.name}</h1>
            <div className="flex items-center gap-1 mt-2">
              <span className="text-xs font-extrabold text-neutral-dark flex items-center gap-1">
                <Star className="w-3.5 h-3.5 text-warning fill-current" />
                {product.rating}
              </span>
              <span className="text-xs text-neutral-muted">({reviews.length} Customer reviews)</span>
            </div>
          </div>

          <div className="py-4 border-t border-b border-neutral-light flex items-center justify-between">
            <div>
              <p className="text-xs text-neutral-muted font-semibold">SKU: <span className="font-mono text-neutral-dark font-bold">{product.sku}</span></p>
              <p className="text-2xl font-extrabold text-neutral-dark mt-1">৳{product.price.toFixed(2)}</p>
            </div>
            <div className="text-right text-xs">
              <p className="text-neutral-muted font-semibold">Category</p>
              <p className="font-bold text-neutral-dark mt-1">{product.category}</p>
            </div>
          </div>

          <div>
            <h3 className="text-xs font-bold text-neutral-dark uppercase tracking-wider mb-2">Description</h3>
            <p className="text-xs text-neutral-body leading-relaxed">{product.description}</p>
          </div>

          {/* Quantity selector and Cart controls */}
          <div className="space-y-4 pt-4 border-t border-neutral-light">
            <div className="flex items-center gap-4">
              <div className="flex items-center border border-neutral-light rounded-md bg-neutral-light overflow-hidden">
                <button
                  onClick={() => setQuantity(Math.max(1, quantity - 1))}
                  className="px-3 py-2 text-xs font-bold hover:bg-neutral-muted/20"
                >
                  -
                </button>
                <span className="px-4 py-2 text-xs font-extrabold text-neutral-dark">{quantity}</span>
                <button
                  onClick={() => setQuantity(quantity + 1)}
                  className="px-3 py-2 text-xs font-bold hover:bg-neutral-muted/20"
                >
                  +
                </button>
              </div>

              <button
                onClick={() => {
                  addToCart(product, quantity);
                  alert(`${quantity} units of "${product.name}" added to cart!`);
                }}
                className="flex-grow bg-primary hover:bg-primary-dark text-neutral-dark text-xs font-bold py-3 rounded-md flex items-center justify-center gap-2 transition-colors cursor-pointer"
              >
                <ShoppingCart className="w-4 h-4" />
                Add to Shopping Cart
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Review System Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        {/* Reviews List */}
        <div className="lg:col-span-2 bg-white p-6 lg:p-8 rounded-lg border border-neutral-light shadow-card space-y-6">
          <h2 className="text-lg font-bold text-neutral-dark border-b border-neutral-light pb-3">
            Customer Reviews ({reviews.length})
          </h2>
          <div className="space-y-4 divide-y divide-neutral-light">
            {reviews.map((rev, i) => (
              <div key={i} className={`${i > 0 ? 'pt-4' : ''}`}>
                <div className="flex items-center justify-between">
                  <h4 className="text-xs font-bold text-neutral-dark">{rev.author}</h4>
                  <span className="text-[10px] text-neutral-muted">{rev.date}</span>
                </div>
                <div className="flex items-center gap-0.5 my-1">
                  {Array.from({ length: 5 }).map((_, idx) => (
                    <Star
                      key={idx}
                      className={`w-3 h-3 ${idx < rev.rating ? 'text-warning fill-current' : 'text-neutral-muted'}`}
                    />
                  ))}
                </div>
                <p className="text-xs text-neutral-body leading-relaxed">{rev.text}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Write a Review Form */}
        <div className="bg-white p-6 rounded-lg border border-neutral-light shadow-card h-fit space-y-4">
          <h2 className="text-xs font-bold text-neutral-dark uppercase tracking-wider border-b border-neutral-light pb-2">
            Write verified Review
          </h2>
          {reviewSuccess && (
            <div className="bg-success/15 border border-success text-success text-[10px] p-2.5 rounded font-semibold flex items-center gap-1">
              <CheckCircle className="w-3.5 h-3.5" />
              Review posted successfully to store logs.
            </div>
          )}
          <form onSubmit={handleAddReview} className="space-y-3">
            <div>
              <label className="block text-[10px] font-bold text-neutral-muted mb-1">Your Name *</label>
              <input
                type="text"
                required
                placeholder="e.g. Rana Ahmed"
                value={newAuthor}
                onChange={(e) => setNewAuthor(e.target.value)}
                className="w-full bg-neutral-light border border-neutral-light rounded p-2 text-xs text-neutral-dark outline-none focus:border-primary"
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-neutral-muted mb-1">Rating Stars *</label>
              <select
                value={newRating}
                onChange={(e) => setNewRating(parseInt(e.target.value))}
                className="w-full bg-neutral-light border border-neutral-light rounded p-2 text-xs text-neutral-dark outline-none focus:border-primary"
              >
                <option value="5">5 Stars (Excellent)</option>
                <option value="4">4 Stars (Good)</option>
                <option value="3">3 Stars (Average)</option>
                <option value="2">2 Stars (Poor)</option>
                <option value="1">1 Star (Very Poor)</option>
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-neutral-muted mb-1">Review Description *</label>
              <textarea
                required
                placeholder="Describe your purchase, shipping velocity, or vendor quality..."
                rows={3}
                value={newText}
                onChange={(e) => setNewText(e.target.value)}
                className="w-full bg-neutral-light border border-neutral-light rounded p-2 text-xs text-neutral-dark outline-none focus:border-primary resize-none"
              ></textarea>
            </div>
            <button
              type="submit"
              className="w-full bg-primary hover:bg-primary-dark text-neutral-dark text-xs font-bold py-2.5 rounded flex items-center justify-center gap-1 transition-colors cursor-pointer"
            >
              <Send className="w-3 h-3" />
              Submit Review
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import {
  User, Mail, Phone, Lock, Eye, EyeOff,
  Loader2, AlertCircle, CheckCircle2, Tag, ArrowRight, ArrowLeft,
  ShoppingBag, Store, Briefcase
} from 'lucide-react';
import { useStore } from '@/store/useStore';

const BUSINESS_CATEGORIES = [
  'Electronics & Gadgets',
  'Fashion & Apparel',
  'Health & Beauty',
  'Home & Kitchen',
  'Groceries & Food',
  'Books & Stationery',
  'Toys & Kids',
  'Sports & Fitness',
  'Automotive & Motor Accessories',
  'Jewelry & Luxury Watches',
  'General Retail'
];

interface FieldProps {
  id: string;
  label: string;
  type?: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  icon: React.ReactNode;
  required?: boolean;
}

function Field({ id, label, type = 'text', value, onChange, placeholder, icon, required = true }: FieldProps) {
  const [show, setShow] = useState(false);
  const isPassword = type === 'password';
  return (
    <div>
      <label htmlFor={id} className="block text-xs font-semibold text-gray-300 mb-1.5">
        {label}{!required && <span className="text-gray-500 text-xs ml-1">(optional)</span>}
      </label>
      <div className="relative">
        <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-500">{icon}</span>
        <input
          id={id}
          type={isPassword ? (show ? 'text' : 'password') : type}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          required={required}
          className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-xl pl-10 pr-10 py-3 text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
        />
        {isPassword && (
          <button
            type="button"
            onClick={() => setShow(!show)}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-300 transition-colors p-1"
            tabIndex={-1}
            aria-label={show ? 'Hide password' : 'Show password'}
          >
            {show ? <EyeOff size={16} /> : <Eye size={16} />}
          </button>
        )}
      </div>
    </div>
  );
}

export default function RegisterPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const login = useStore((s) => s.login);

  // Account Type: 'customer' | 'seller'
  const initialType = searchParams.get('type') === 'seller' ? 'seller' : 'customer';
  const [accountType, setAccountType] = useState<'customer' | 'seller'>(initialType);

  // Form States
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [storeName, setStoreName] = useState('');
  const [businessCategory, setBusinessCategory] = useState('Electronics & Gadgets');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [referralCode, setReferralCode] = useState('');
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    if (searchParams.get('type') === 'seller') {
      setAccountType('seller');
    }
  }, [searchParams]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!fullName.trim()) {
      setError('Please enter your full name.');
      return;
    }
    if (!email.trim() || !email.includes('@')) {
      setError('Please enter a valid email address.');
      return;
    }
    if (accountType === 'seller' && !storeName.trim()) {
      setError('Please enter your Store / Business name.');
      return;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match.');
      return;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }
    if (!termsAccepted) {
      setError('Please accept the Terms of Service and Privacy Policy to continue.');
      return;
    }

    setLoading(true);

    try {
      // Clear old session credentials first to guarantee clean account isolation
      if (typeof window !== 'undefined') {
        localStorage.removeItem('zibonbaba_token');
        localStorage.removeItem('zibonbaba_user');
        localStorage.removeItem('zibonbaba_role');
        sessionStorage.clear();
      }

      const body: Record<string, any> = {
        fullName: fullName.trim(),
        email: email.trim().toLowerCase(),
        phone: phone.trim() || undefined,
        password,
        role: accountType === 'seller' ? 'VENDOR_ADMIN' : 'CUSTOMER',
      };

      if (accountType === 'seller') {
        body.storeName = storeName.trim();
        body.businessType = businessCategory;
      } else if (referralCode.trim()) {
        body.referralCode = referralCode.trim();
      }

      const res = await fetch('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      const data = await res.json();
      if (!res.ok) {
        setError(data.error || data.message || 'Registration failed. Please try again.');
        return;
      }

      // Establish fresh isolated session
      if (data.accessToken && typeof window !== 'undefined') {
        localStorage.setItem('zibonbaba_token', data.accessToken);
        localStorage.setItem('zibonbaba_user', JSON.stringify(data.user));
        localStorage.setItem('zibonbaba_role', data.user.role);
        document.cookie = `zibonbaba_token=${data.accessToken}; path=/; max-age=604800; SameSite=Lax`;
        document.cookie = `zibonbaba_role=${data.user.role}; path=/; max-age=604800; SameSite=Lax`;
        document.cookie = `zibonbaba_user=${encodeURIComponent(JSON.stringify(data.user))}; path=/; max-age=604800; SameSite=Lax`;

        useStore.setState({
          isLoggedIn: true,
          token: data.accessToken,
          role: accountType === 'seller' ? 'vendor' : 'customer',
          username: data.user?.fullName || data.user?.email || 'User',
          userEmail: data.user?.email || '',
          cart: [],
          orders: []
        });
      }

      setSuccess(true);
    } catch {
      setError('Could not connect to the server. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950 text-white relative overflow-hidden px-4">
        <Link
          href="/"
          className="absolute top-4 left-4 z-50 p-2.5 rounded-full bg-white/5 hover:bg-white/10 text-gray-400 hover:text-white transition-colors border border-white/10 backdrop-blur-sm"
        >
          <ArrowLeft size={20} />
        </Link>

        <div className="absolute inset-0 bg-gradient-to-br from-gray-900 via-gray-950 to-gray-900" />
        <div className="absolute top-1/3 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] rounded-full bg-primary/10 blur-[130px] pointer-events-none" />

        <div className="relative z-10 w-full max-w-md text-center backdrop-blur-xl bg-white/5 border border-white/10 rounded-3xl p-8 sm:p-10 shadow-2xl">
          <div className="w-16 h-16 sm:w-20 sm:h-20 bg-green-500/20 border border-green-500/30 rounded-2xl flex items-center justify-center mx-auto mb-5 text-green-400 shadow-glow">
